"""## Ensemble infinite temperature autocorrelation function


$$C_i(nT) = \langle \psi_0 | [\sigma^z_i(nT) ][\sigma^z_i(0) ] | \psi_0 \rangle $$
"""

"""Module: autocorrelation
Provides: compute_multisite_autocorrelation,
          compute_ensemble_average_batched,
          test_single_state_autocorrelation,
          run_autocorr_coupling_comparison
Depends on: hamiltonian, evolution, observables, states

Multi-site ensemble-averaged infinite-temperature autocorrelation:

    C_j(nT) = (1/B) sum_{alpha=1}^{B}
              Re[ <psi_alpha| sigma^z_j(nT) sigma^z_j(0) |psi_alpha> ]

Uses the stacked two-ket method: for M measurement sites, evolve
(1 + M) * B kets per block instead of 2 * B.  The Psi kets are
shared across all sites.

Memory layout per block of B states and M sites:

    Z[:, 0     : B    ]  =  Psi kets       (shared reference)
    Z[:, B     : 2B   ]  =  Phi_0 kets     (site 0)
    Z[:, 2B    : 3B   ]  =  Phi_1 kets     (site 1)
    ...
    Z[:, m*B   : (m+1)*B] = Phi_{m-1} kets (site m-1)

Complexity per (L, n_periods, M sites, B states):

    T_evolve = O(n_periods * (1 + M) * B * C_ket)

where C_ket = 2 * n_sub * (6 + 5*L) * N_s  (Trotter cost per ket).

    T_measure = O(n_periods * M * N_s * B)   (diagonal sigma^z, negligible)
"""
import numpy as np
import time

# ============================================================================
# MULTI-SITE AUTOCORRELATION (primary API)
# ============================================================================

def compute_multisite_autocorrelation(
    random_states,
    apply_U,
    observables,
    n_periods,
    *,
    batch_size=None,
    store_all=True,
    return_real=True,
    verbose=True,
    progress_interval=2.0,
):
    """
    Compute ensemble-averaged autocorrelation at multiple sites simultaneously.

    For M measurement sites, shares Psi evolution across all sites.
    Cost: O(n_periods * (1 + M) * B * C_ket) instead of
          O(n_periods * 2 * M * B * C_ket) for M independent runs.

    Parameters
    ----------
    random_states : ndarray (Ns, B) or list of (Ns,) vectors
        Ensemble of B random initial states.
    apply_U : callable
        Floquet propagator: psi (Ns,) -> U_F psi, or (Ns, B) -> U_F @ [columns].
    observables : dict[str, callable] or callable
        If dict: {label: apply_O} where apply_O handles (Ns,) or (Ns, B).
                 Example: {'bulk': apply_sigma_z_bulk, 'edge': apply_sigma_z_edge}
        If callable: treated as {'obs': apply_O} for backward compatibility.
    n_periods : int
        Number of Floquet periods to evolve.
    batch_size : int or None
        States per parallel block.  None -> min(50, num_states).
    store_all : bool
        If True, store per-state traces C_all[label] of shape (B, n_periods+1).
    return_real : bool
        If True, return Re[C].
    verbose : bool
        Progress output.
    progress_interval : float
        Seconds between progress prints.

    Returns
    -------
    results : dict[str, dict]
        results[label] = {
            'times': ndarray (n_periods+1,),
            'C_avg': ndarray (n_periods+1,),
            'C_all': ndarray (B, n_periods+1) or None
        }
    """
    # ------------------------------------------------------------------
    # 0. Normalise observables to dict
    # ------------------------------------------------------------------
    if callable(observables) and not isinstance(observables, dict):
        observables = {'obs': observables}

    obs_labels = list(observables.keys())
    obs_funcs = [observables[k] for k in obs_labels]
    M = len(obs_labels)

    # ------------------------------------------------------------------
    # 1. Input handling
    # ------------------------------------------------------------------
    if isinstance(random_states, np.ndarray) and random_states.ndim == 2:
        Psi_all = random_states.astype(np.complex128)
        Ns, num_states = Psi_all.shape
    elif isinstance(random_states, list):
        num_states = len(random_states)
        Ns = random_states[0].shape[0]
        Psi_all = np.column_stack(random_states).astype(np.complex128)
    else:
        raise TypeError("random_states must be list or 2D array")

    # ------------------------------------------------------------------
    # 2. Batch geometry
    # ------------------------------------------------------------------
    if batch_size is None:
        batch_size = min(50, num_states)
    batch_size = min(batch_size, num_states)

    n_full_blocks = num_states // batch_size
    remainder = num_states % batch_size
    n_blocks = n_full_blocks + (1 if remainder > 0 else 0)

    # ------------------------------------------------------------------
    # 3. Allocate accumulators
    # ------------------------------------------------------------------
    times = np.arange(n_periods + 1, dtype=np.float64)

    C_sum = {}          # C_sum[label] : complex128 (n_periods+1,)
    C_all_store = {}    # C_all_store[label] : complex128 (num_states, n_periods+1)

    for label in obs_labels:
        C_sum[label] = np.zeros(n_periods + 1, dtype=np.complex128)
        if store_all:
            C_all_store[label] = np.zeros((num_states, n_periods + 1),
                                          dtype=np.complex128)

    # ------------------------------------------------------------------
    # 4. Progress bookkeeping
    # ------------------------------------------------------------------
    # Work unit = one (state, period) pair.  Evolution of (1+M) kets is
    # counted as one work unit per state since the Psi ket is shared.
    total_work = num_states * (n_periods + 1)
    work_done = 0

    if verbose:
        print(f"\n  Multisite autocorrelation (stacked two-ket):")
        print(f"    Sites: {M}  ({', '.join(obs_labels)})")
        print(f"    States: {num_states}, Periods: {n_periods}, Batches: {n_blocks}")
        print(f"    Batch size: {batch_size}")
        print(f"    Kets per block: (1 + {M}) * {batch_size} "
              f"= {(1 + M) * batch_size}")
        mem_bytes = (1 + M) * batch_size * Ns * 16
        print(f"    Block memory: {mem_bytes / 2**20:.1f} MiB")
        print()

    total_start = time.time()
    last_print = total_start

    # ------------------------------------------------------------------
    # 5. Main loop over blocks
    # ------------------------------------------------------------------
    for block_idx in range(n_blocks):
        start_state = block_idx * batch_size
        end_state = start_state + (batch_size if block_idx < n_full_blocks
                                   else remainder)
        B = end_state - start_state          # effective block width

        Psi0_block = Psi_all[:, start_state:end_state]  # (Ns, B)

        # ----------------------------------------------------------
        # Build stacked state Z = [ Psi | Phi_0 | ... | Phi_{M-1} ]
        # Shape: (Ns, (1 + M) * B),  C-contiguous complex128
        # ----------------------------------------------------------
        Z = np.empty((Ns, (1 + M) * B), dtype=np.complex128)
        Z[:, :B] = Psi0_block                            # Psi kets
        for m, apply_O in enumerate(obs_funcs):
            Z[:, (1 + m) * B : (2 + m) * B] = apply_O(Psi0_block)  # Phi_m

        # Per-site accumulators for this block
        C_block = {label: np.zeros((B, n_periods + 1), dtype=np.complex128)
                   for label in obs_labels}

        # ----------------------------------------------------------
        # Time-step loop
        # ----------------------------------------------------------
        for n in range(n_periods + 1):
            Psi_view = Z[:, :B]                          # (Ns, B)

            # Measure C_j(nT) = <Psi_n | O_j | Phi_n^{(j)}>  for each site j
            for m, (label, apply_O) in enumerate(zip(obs_labels, obs_funcs)):
                Phi_view = Z[:, (1 + m) * B : (2 + m) * B]
                O_Phi = apply_O(Phi_view)                # sigma^z_j |Phi_j>
                # inner product per state:  sum_s conj(Psi[s,b]) * O_Phi[s,b]
                C_block[label][:, n] = np.sum(
                    np.conj(Psi_view) * O_Phi, axis=0)

            # Evolve ALL kets for next step (single batched call)
            if n < n_periods:
                Z = apply_U(Z)

            # Progress
            work_done += B
            now = time.time()
            if verbose and (now - last_print >= progress_interval):
                pct = 100.0 * work_done / total_work
                elapsed = now - total_start
                rate = work_done / elapsed if elapsed > 0 else 0.0
                eta = (total_work - work_done) / rate if rate > 0 else 0.0
                print(f"    Progress: {pct:5.1f}% | "
                      f"Block {block_idx + 1}/{n_blocks}, "
                      f"Step {n + 1}/{n_periods + 1} | "
                      f"ETA: {eta:.0f}s")
                last_print = now

        # Accumulate into global sums
        for label in obs_labels:
            if store_all:
                C_all_store[label][start_state:end_state, :] = C_block[label]
            C_sum[label] += np.sum(C_block[label], axis=0)

    # ------------------------------------------------------------------
    # 6. Finalize
    # ------------------------------------------------------------------
    total_time = time.time() - total_start

    results = {}
    for label in obs_labels:
        C_avg = C_sum[label] / num_states

        if verbose:
            print(f"\n  [{label}] C(0) = {np.real(C_avg[0]):.6f} "
                  f"(should be 1.0 for sigma^2=I)")
            print(f"  [{label}] C({n_periods}T) = {np.real(C_avg[-1]):.6f}")

        if return_real:
            C_avg = np.real(C_avg)

        entry = {'times': times, 'C_avg': C_avg}

        if store_all:
            c_all = C_all_store[label]
            if return_real:
                c_all = np.real(c_all)
            entry['C_all'] = c_all
        else:
            entry['C_all'] = None

        results[label] = entry

    if verbose:
        print(f"\n  Complete in {total_time:.1f}s "
              f"({total_time / n_periods:.3f} s/period)")

    return results

import numpy as np
import matplotlib.pyplot as plt
def test_single_state_autocorrelation(apply_U, apply_O, Ns, n_periods=20, seed=42):
    """
    Test autocorrelation for a single state to verify formula correctness.


    C(nT) = ⟨ψ₀|O(nT) O(0)|ψ₀⟩ = ⟨Ψₙ|O|Φₙ⟩


    For O = σ^z: C(0) = ⟨ψ|σ^z σ^z|ψ⟩ = ⟨ψ|I|ψ⟩ = 1
    """
    print("\n  Single-state diagnostic:")


    np.random.seed(seed)
    psi0 = np.random.randn(Ns) + 1j * np.random.randn(Ns)
    psi0 = psi0 / np.linalg.norm(psi0)
    psi0 = psi0.astype(np.complex128)


    # Two-ket method
    Psi = psi0.copy()
    Phi = apply_O(psi0.copy())


    C = np.zeros(n_periods + 1, dtype=np.complex128)


    for n in range(n_periods + 1):
        O_Phi = apply_O(Phi)
        C[n] = np.vdot(Psi, O_Phi)


        if n < n_periods:
            Psi = apply_U(Psi)
            Phi = apply_U(Phi)


    print(f"    C(0) = {np.real(C[0]):.6f} (expect 1.0)")
    print(f"    C(1) = {np.real(C[1]):.6f}")
    print(f"    C({n_periods}) = {np.real(C[-1]):.6f}")


    if abs(np.real(C[0]) - 1.0) > 0.01:
        print("    ⚠ WARNING: C(0) ≠ 1, check σ^z implementation!")
    else:
        print("    ✓ C(0) = 1 verified")


    return C
