h_0_list = [2, 4, 6, 8]             # h_0 = 2*J_0 for all (or provide list)
g = 1.0                        # Transverse field strength
NTP = 2                        # Time period factor: T = NTP * π/J_0
site_i = L // 2                # Bulk site for measurement
n_steps = 200                  # Number of Floquet periods
num_states = 32                # Number of states in ensemble
batch_size = 32                # States processed in parallel (None=auto)
seed = 42                      # Random seed
store_all = True               # Store individual traces

# ============================================================================

print(f"\n{'='*70}")
print("PARAMETERS")
print(f"{'='*70}")
print(f"  L = {L}")
print(f"  J_0_list = {J_0_list}")
print(f"  h_0_relation = {h_0_list}")
print(f"  g = {g}")
print(f"  T = {NTP}π/J_0")
print(f"  site_i = {site_i}")
print(f"  n_steps = {n_steps}")
