# --- Panel (a): D_max / D  vs  L ---
def fib(n):
    a, b = 1, 1
    for _ in range(n - 1):
        a, b = b, a + b
    return a

L_vals = np.arange(4, 19)
D_max  = np.array([fib(L) for L in L_vals])
D_full = np.array([2**L for L in L_vals])
ratio  = D_max / D_full

# --- Panel (b): n*(J_0) bulk site ---
J0_all     = np.array([1.0, 1.5, 2.0, 2.5, 2.75, 3.0, 3.2, 3.4, 3.6, 3.8, 4.0])
n_star_all = np.array([2,   5,   11,  30,  46,   66,  130, 205, 351, 598, 958])

# Fit range: J_0 >= 2.5
mask_fit = J0_all >= 2.5
J0_fit   = J0_all[mask_fit]
n_fit    = n_star_all[mask_fit]

def exp_model(x, A, B):
    return A * np.exp(B * x)

slope, intercept = np.polyfit(J0_fit, np.log(n_fit), 1)
popt, pcov = curve_fit(exp_model, J0_fit, n_fit,
                        p0=[np.exp(intercept), slope], maxfev=10000)
A, B = popt
perr = np.sqrt(np.diag(pcov))

n_pred = exp_model(J0_fit, *popt)
ss_res = np.sum((n_fit - n_pred)**2)
ss_tot = np.sum((n_fit - np.mean(n_fit))**2)
R2 = 1 - ss_res / ss_tot

J0_dense = np.linspace(2.5, 4.15, 300)
n_dense  = exp_model(J0_dense, *popt)

# ════════════════════════════════════════════════════════════════════
# FIGURE
# ════════════════════════════════════════════════════════════════════
