ax0.plot(L_vals, ratio,
         color='black', marker='o', markersize=10,
         markeredgecolor='black', markerfacecolor='black',
         linewidth=1.2, zorder=3)

# Golden ratio asymptote
phi = (1 + np.sqrt(5)) / 2
L_dense_a = np.linspace(3.5, 18.5, 200)
asymptote = (phi / 2.0)**L_dense_a / np.sqrt(5)
ax0.plot(L_dense_a, asymptote,
         color='#d62728', linewidth=1.8, linestyle='--', zorder=2,
         label=r'$(\varphi/2)^{L}/\!\sqrt{5}$')

ax0.set_xlabel(r'$L$', fontsize=25, labelpad=-5)
ax0.set_ylabel(r'$D_{\max}/\mathcal{D}$', fontsize=25, labelpad=2)

