ax0.legend(fontsize=20, frameon=False, loc='upper right',
           handlelength=1.8, handletextpad=0.4, labelspacing=0.3,
           borderaxespad=0.3)

ax0.text(-0.02, 1.05, r'$\mathbf{(a)}$',
         transform=ax0.transAxes, fontsize=26, va='bottom', ha='left')

# ====================================================================
