"""# Decay analysis"""

# Commented out IPython magic to ensure Python compatibility.
# %matplotlib inline
# %config InlineBackend.figure_format = 'retina'

"""
Autocorrelation decay time n*(J_0) — Floquet Ising chain.
Notebook-friendly: runs top-to-bottom, plots inline via plt.show().

Physics
-------
    H_±  = ∓ J_0 Σ_i σ^z_i σ^z_{i+1}  ∓ h_0 Σ_i σ^z_i  − g Σ_i σ^x_i
    T    = 2π / J_0        (stroboscopic freezing)
    h_0  = 2 J_0           (deep-drive, J_0 = h_0/2)
    g    = 1               (integrability-breaking perturbation)

Observable  (two-ket method, infinite-temperature trace):
    C_j(nT) = (1/B) Σ_α Re⟨Ψ_n^α | σ^z_j | Φ_n^α⟩
    where   |Ψ_n⟩ = U_F^n |ψ_α⟩ ,   |Φ_n⟩ = U_F^n σ^z_j |ψ_α⟩

Early stopping:
    After each Floquet step, check rolling window of last W periods.
    If  mean(|C|)  over that window  < stop_threshold,  stop and
    move to the next J_0.

Cost per autocorrelation step (B states):
    2 × n_sub × (6 + 5L) × N_s × B   FLOPs
    (4th-order Yoshida–Suzuki split-operator — NO dense matrices)
"""

# ═══════════════════════════════════════════════════════════════════
# Imports
# ═══════════════════════════════════════════════════════════════════
import time
import numpy as np
import matplotlib.pyplot as plt
from matplotlib.ticker import AutoMinorLocator

# ╔════════════════════════════════════════════════════════════════╗
# ║                    TUNABLE PARAMETERS                          ║
# ║  (edit this block and re-run — everything else adapts)         ║
# ╚════════════════════════════════════════════════════════════════╝

L            = 8                         # chain length  (N_s = 2^L)
g            = 1                        # transverse field
SITE_I       = None                       # measurement site (None → L//2)

NUM_STATES   = 10                         # Haar-random states for ⟨…⟩
BATCH_SIZE   = 10                         # parallel batch (≤ NUM_STATES)
SEED         = 42                         # reproducibility

EPSILON      = 0.22                        # |C| < ε  ⟹  "decayed"
CONSEC       = 5                          # consecutive periods for n*

N_STEPS      = 5000                       # max Floquet periods per J_0

J_0_VALUES   = [2, 2.5, 3, 3.25, 3.5]

TROTTER_TOL  = 1e-5                       # per-period Trotter error target

# Early-stopping parameters
STOP_WINDOW  = 10                         # rolling window length (periods)
STOP_THRESH  = 0.21                        # mean(|C|) over window < this → stop


# ╔════════════════════════════════════════════════════════════════╗
# ║    TWO-KET LOOP WITH EARLY STOPPING  (replaces the library)   ║
# ╚════════════════════════════════════════════════════════════════╝

def compute_autocorr_earlystop(
    random_states,      # (Ns, B) complex128 matrix
    apply_U,            # callable: X -> U_F X, accepts (Ns,) or (Ns,B)
    apply_O,            # callable: X -> O X,   accepts (Ns,) or (Ns,B)
    n_max,              # maximum Floquet periods
    *,
    stop_window=10,     # rolling window length
    stop_thresh=0.1,    # stop when mean(|C|) over window < this
    print_every=30.0,   # seconds between progress prints
):
    """
    Two-ket autocorrelation with early stopping, but evolve both ket sets
    in one batched apply_U call.

    Mathematical definitions
    ------------------------
    Let
        Ns = Hilbert-space dimension,
        B  = number of random states,
        U_F = one-period Floquet propagator,
        O   = observable operator (here typically sigma^z_i).

    For each random state |psi_alpha>, define
        |Psi_n^alpha> = U_F^n |psi_alpha>
        |Phi_n^alpha> = U_F^n O |psi_alpha>

    The ensemble-averaged autocorrelation is
        C(nT) = (1/B) * sum_alpha Re[ <Psi_n^alpha| O |Phi_n^alpha> ].

    Parameters
    ----------
    random_states : ndarray, shape (Ns, B)
        Columns are independent normalized initial states.
    apply_U : callable
        Batched Floquet propagator.
    apply_O : callable
        Batched observable application.
    n_max : int
        Maximum number of Floquet periods.
    stop_window : int
        Early-stop rolling window length.
    stop_thresh : float
        Stop if mean(|C|) over last `stop_window` values drops below this.
    print_every : float
        Progress print interval in seconds.

    Returns
    -------
    C_avg : ndarray, shape (actual_steps + 1,), dtype float64
        Autocorrelation values from n = 0 up to the stopping step.
    stopped_early : bool
        True if early stopping triggered.
    """
    Psi0 = np.asarray(random_states, dtype=np.complex128)
    if Psi0.ndim != 2:
        raise ValueError(f"random_states must have shape (Ns, B), got ndim={Psi0.ndim}")

    Ns, B = Psi0.shape
    if B == 0:
        raise ValueError("random_states must contain at least one state")

    # Build one combined block:
    #   X[:, :B]   = Psi_n
    #   X[:, B:]   = Phi_n
    X = np.empty((Ns, 2 * B), dtype=np.complex128)
    X[:, :B] = Psi0
    X[:, B:] = apply_O(Psi0.copy())

    C_list = []
    t0 = time.time()
    t_last = t0

    for n in range(n_max + 1):
        Psi = X[:, :B]
        Phi = X[:, B:]

        # Measure: C(nT) = (1/B) sum_alpha Re <Psi_n|O|Phi_n>
        O_Phi = apply_O(Phi)  # (Ns, B)

        # Per-state overlaps:
        # c_alpha = sum_s conj(Psi[s,alpha]) * (O_Phi[s,alpha])
        c_per_state = np.einsum("ij,ij->j", Psi.conj(), O_Phi, optimize=True)

        C_n = float(np.real(np.mean(c_per_state)))
        C_list.append(C_n)

        # Early stopping
        if n >= stop_window:
            mean_abs = float(np.mean(np.abs(C_list[-stop_window:])))
            if mean_abs < stop_thresh:
                now = time.time()
                print(
                    f"    ✂ Early stop at n = {n}: "
                    f"mean(|C|) over last {stop_window} = {mean_abs:.4f} "
                    f"< {stop_thresh}  [{now - t0:.1f}s elapsed]"
                )
                return np.asarray(C_list, dtype=np.float64), True

        # Evolve BOTH Psi and Phi in ONE call
        if n < n_max:
            X = apply_U(X)

        # Progress print
        now = time.time()
        if now - t_last >= print_every:
            pct = 100.0 * n / n_max if n_max > 0 else 100.0
            elapsed = now - t0
            rate = (n + 1) / elapsed if elapsed > 0 else 0.0
            eta = (n_max - n) / rate if rate > 0 else 0.0
            print(
                f"    n = {n:5d}/{n_max}  ({pct:5.1f}%)  "
                f"|C| = {abs(C_n):.4f}  ETA {eta:.0f}s"
            )
            t_last = now

    return np.asarray(C_list, dtype=np.float64), False


# ╔════════════════════════════════════════════════════════════════╗
# ║              METRIC EXTRACTION  (pure function)                ║
# ╚════════════════════════════════════════════════════════════════╝

def extract_decay_metrics(C_avg, epsilon=EPSILON, consec=CONSEC):
    """
    Returns dict { n_1e, n_half, n_star, C_infty }
    """
    N = len(C_avg)

    n_1e = None
    for n in range(1, N):
        if abs(C_avg[n]) < 1.0 / np.e:
            n_1e = n; break

    n_half = None
    for n in range(1, N):
        if abs(C_avg[n]) < 0.5:
            n_half = n; break

    n_star, count = None, 0
    for n in range(1, N):
        if abs(C_avg[n]) < epsilon:
            count += 1
            if count >= consec:
                n_star = n - consec + 1; break
        else:
            count = 0

    tail_start = max(N // 2, 1)
    C_infty    = float(np.mean(np.abs(C_avg[tail_start:])))

    return dict(n_1e=n_1e, n_half=n_half, n_star=n_star, C_infty=C_infty)


# ╔════════════════════════════════════════════════════════════════╗
# ║          COMPUTE ALL J_0 POINTS  (loop, all sparse)            ║
# ╚════════════════════════════════════════════════════════════════╝

si = L // 2 if SITE_I is None else SITE_I

results = {}
total_t0 = time.time()

print("=" * 72)
print("AUTOCORRELATION DECAY SCAN  (with early stopping)")
print(f"  L = {L},  g = {g},  site j = {si},  N_s = {1 << L}")
print(f"  h_0 = 2 J_0,  T = 2π/J_0,  n_steps_max = {N_STEPS}")
print(f"  Ensemble: {NUM_STATES} states,  seed = {SEED}")
print(f"  Decay criterion: |C| < {EPSILON} for {CONSEC} consecutive")
print(f"  Early stop: mean(|C|) over {STOP_WINDOW} steps < {STOP_THRESH}")
print(f"  J_0 values: {J_0_VALUES}")
print("=" * 72)

for idx, J_0 in enumerate(J_0_VALUES):
    h_0 = 2.0 * J_0
    TP  = 2.0 * np.pi / J_0

    print(f"\n{'─'*72}")
    print(f"[{idx+1}/{len(J_0_VALUES)}]  J_0 = {J_0},  h_0 = {h_0},  "
          f"T = 2π/{J_0} = {TP:.5f}")
    print(f"{'─'*72}")

    t0 = time.time()

    # 1. Sparse Hamiltonians  (CSR, never densified)
    ising = FloquetIsingChain(L=L, J_0=J_0, h_0=h_0, g=g, TP=TP, hbar=1.0)
    ising.build_hamiltonians()

    # 2. Split-operator Trotter propagator  O(5 L N_s) per substep
    apply_U = make_floquet_propagator(ising, tol=TROTTER_TOL, verbose=True)

    # 3. Diagonal σ^z operator  O(N_s)
    apply_sz = make_sigma_z_matvec(ising, site_i=si)

    # 4. Haar-random states  (N_s, B) complex128
    states = generate_random_states(
        ising.Ns, num_states=NUM_STATES, seed=SEED,
        verbose=False, return_format='matrix'
    )

    # 5. Two-ket autocorrelation WITH early stopping
    C_avg, stopped = compute_autocorr_earlystop(
        states, apply_U, apply_sz,
        n_max=N_STEPS,
        stop_window=STOP_WINDOW,
        stop_thresh=STOP_THRESH,
        print_every=30.0,
    )

    wall      = time.time() - t0
    n_actual  = len(C_avg) - 1          # last index
    times     = np.arange(len(C_avg), dtype=np.float64)
    m         = extract_decay_metrics(C_avg)

    print(f"\n  Wall: {wall:.1f}s  "
          f"({wall/max(n_actual,1)*1e3:.1f} ms/step, "
          f"{n_actual} steps{'  [EARLY STOP]' if stopped else ''})")
    print(f"  C(0) = {C_avg[0]:.6f},  C({n_actual}T) = {C_avg[-1]:+.6f}")
    print(f"  n_{{1/e}} = {m['n_1e']},  n_{{1/2}} = {m['n_half']},  "
          f"n*(ε) = {m['n_star']},  C_∞ = {m['C_infty']:.6f}")

    results[J_0] = dict(
        J_0=J_0, h_0=h_0, T=TP,
        n_max=N_STEPS, n_actual=n_actual, stopped_early=stopped,
        C_avg=C_avg, times=times,
        n_sub=apply_U.n_sub, wall_time=wall,
        **m,
    )

total_wall = time.time() - total_t0
print(f"\n{'='*72}")
print(f"ALL DONE — total {total_wall:.0f}s  "
      f"({total_wall/len(J_0_VALUES):.0f}s avg / J_0)")
print(f"{'='*72}")


# ╔════════════════════════════════════════════════════════════════╗
# ║                     SUMMARY TABLE                              ║
# ╚════════════════════════════════════════════════════════════════╝

J_0_list = sorted(results.keys())

print(f"\n{'J_0':>6}  {'h_0':>6}  {'n_sub':>5}  "
      f"{'ran':>6}  {'stop?':>5}  "
      f"{'n_1/2':>6}  {'n_1/e':>6}  {'n*':>8}  "
      f"{'C_inf':>7}  {'wall':>7}")
print("─" * 80)
for J in J_0_list:
    r  = results[J]
    ns = r['n_star']
    print(f"{J:6.2f}  {r['h_0']:6.2f}  "
          f"{r['n_sub']:5d}  "
          f"{r['n_actual']:6d}  "
          f"{'  Y' if r['stopped_early'] else '  N':>5}  "
          f"{r['n_half'] if r['n_half'] else '—':>6}  "
          f"{r['n_1e'] if r['n_1e'] else '—':>6}  "
          f"{str(ns) if ns else '—':>8}  "
          f"{r['C_infty']:7.4f}  "
          f"{r['wall_time']:7.1f}s")


# ╔════════════════════════════════════════════════════════════════╗
# ║           FIGURE 1 — C(nT) curves  (4-panel overview)         ║
# ╚════════════════════════════════════════════════════════════════╝

n_J    = len(J_0_list)
colors = plt.cm.plasma(np.linspace(0.1, 0.9, n_J))

suptxt = (f'$L={L}$, $g={g}$, $h_0=2J_0$, $T=2\\pi/J_0$, '
          f'site $j={si}$, {NUM_STATES} states')

fig, axes = plt.subplots(2, 2, figsize=(16, 11))

# (a) semi-log ────────────────────────────────────────────────────
ax = axes[0, 0]
for i, J0 in enumerate(J_0_list):
    n = results[J0]['times']; C = results[J0]['C_avg']
    m = n > 0
    ax.plot(n[m], C[m], '-', color=colors[i], lw=1.3,
            label=f'$J_0={J0}$ ({len(C)-1} steps)', alpha=0.85)
    nd = results[J0]['n_star']
    if nd is not None:
        ax.axvline(nd, color=colors[i], ls=':', alpha=0.35, lw=1)
ax.axhline(EPSILON, color='red', ls='--', lw=1.5,
           label=f'$\\epsilon={EPSILON}$')
ax.axhline(-EPSILON, color='red', ls='--', lw=1, alpha=0.4)
ax.axhline(0, color='k', lw=0.4, alpha=0.3)
ax.set_xscale('log')
ax.set_xlabel('$n$'); ax.set_ylabel(r'$C_j(nT)$')
ax.set_title('(a) Semi-log', fontweight='bold')
ax.legend(fontsize=7, ncol=2); ax.grid(True, alpha=0.2, which='both')

# (b) log-log |C| ────────────────────────────────────────────────
ax = axes[0, 1]
for i, J0 in enumerate(J_0_list):
    n = results[J0]['times']; C = results[J0]['C_avg']
    m = n > 0
    ax.plot(n[m], np.maximum(np.abs(C[m]), 1e-16), '-',
            color=colors[i], lw=1.3, label=f'$J_0={J0}$', alpha=0.85)
ax.axhline(EPSILON, color='red', ls='--', lw=1.5)
ax.set_xscale('log'); ax.set_yscale('log')
ax.set_xlabel('$n$'); ax.set_ylabel(r'$|C_j(nT)|$')
ax.set_title('(b) Log-log', fontweight='bold')
ax.legend(fontsize=7, ncol=2); ax.grid(True, alpha=0.2, which='both')

# (c) early time  (n ≤ 50) ───────────────────────────────────────
ax = axes[1, 0]
for i, J0 in enumerate(J_0_list):
    n = results[J0]['times']; C = results[J0]['C_avg']
    m = n <= 50
    ax.plot(n[m], C[m], 'o-', color=colors[i], lw=1.2, ms=3,
            label=f'$J_0={J0}$', alpha=0.85)
ax.axhline(EPSILON, color='red', ls='--', lw=1.2, alpha=0.5)
