ax.set_xlabel('$n$'); ax.set_ylabel(r'$C_j(nT)$')
ax.set_title('(c) Early time ($n \\leq 50$)', fontweight='bold')
ax.legend(fontsize=7, ncol=2); ax.grid(True, alpha=0.3)

# (d) all curves full length ──────────────────────────────────────
ax = axes[1, 1]
for i, J0 in enumerate(J_0_list):
    n = results[J0]['times']; C = results[J0]['C_avg']
    lab = (f'$J_0={J0}$: {results[J0]["n_actual"]} steps, '
           f'$C_\\infty$={results[J0]["C_infty"]:.3f}')
    ax.plot(n, C, '-', color=colors[i], lw=0.8, label=lab, alpha=0.8)
ax.axhline(0, color='k', lw=0.4, alpha=0.3)
ax.axhline(EPSILON, color='red', ls='--', lw=1.2, alpha=0.6)
ax.axhline(-EPSILON, color='red', ls='--', lw=0.8, alpha=0.3)
ax.set_xlabel('$n$'); ax.set_ylabel(r'$C_j(nT)$')
ax.set_title('(d) Full traces (early-stopped curves are shorter)',
             fontweight='bold')
ax.legend(fontsize=6, ncol=2); ax.grid(True, alpha=0.3)

fig.suptitle(f'Autocorrelation $C_j(nT)$ — {suptxt}', fontsize=12, y=1.01)
