# (b) C_∞ (frozen fraction) ──────────────────────────────────────
Cinf = np.array([results[J]['C_infty'] for J in J_0_list])
ax_b.plot(J_0_list, Cinf, 'D-', color='#8e44ad', lw=2.5, ms=10,
          mfc='#9b59b6', zorder=3)
ax_b.axhline(0, color='k', lw=0.4, alpha=0.3)
ax_b.axhline(EPSILON, color='red', ls='--', lw=1.2, alpha=0.5,
             label=f'$\\epsilon={EPSILON}$')
ax_b.set_xlabel('$J_0$', fontsize=14)
ax_b.set_ylabel('$C_\\infty$  (frozen fraction)', fontsize=14)
ax_b.set_title('(b) HSF frozen fraction', fontweight='bold')
ax_b.legend(fontsize=11); ax_b.grid(True, alpha=0.3)
ax_b.set_ylim(bottom=-0.005)
ax_b.xaxis.set_minor_locator(AutoMinorLocator())

# (c) n*(ε) vs J_0 ───────────────────────────────────────────────
J_star = [J for J in J_0_list if results[J]['n_star'] is not None]
n_star = [results[J]['n_star'] for J in J_star]
J_none = [J for J in J_0_list if results[J]['n_star'] is None]

if J_star:
    ax_c.semilogy(J_star, n_star, 'o-', color='#2c3e50', lw=2, ms=9,
                  mfc='#e74c3c',
                  label=f'$n^*(\\epsilon={EPSILON})$', zorder=3)

    if len(J_star) >= 3:
        Ja = np.array(J_star, dtype=float)
        Na = np.array(n_star, dtype=float)
        coeffs = np.polyfit(Ja, np.log(Na), 1)
        alpha, lnA = coeffs
        J_fine = np.linspace(Ja[0], max(Ja[-1], J_0_list[-1]) + 0.1, 200)
        ax_c.semilogy(J_fine, np.exp(lnA + alpha * J_fine), '--',
                      color='#3498db', lw=1.5,
                      label=f'Fit: $n^* \\approx {np.exp(lnA):.1f}'
                            f'\\,e^{{{alpha:.2f}\\,J_0}}$')
        print(f"\nExponential fit:  n*(J_0) ≈ {np.exp(lnA):.2f} "
              f"× exp({alpha:.3f} · J_0)")

for J in J_none:
    na = results[J]['n_actual']
    Ci = results[J]['C_infty']
    ax_c.semilogy(J, na, 'v', color='gray', ms=11, zorder=3)
    ax_c.annotate(f'$C_\\infty$={Ci:.3f}\n(no decay in {na})',
                  (J, na), textcoords='offset points',
                  xytext=(8, -5), fontsize=7, color='gray',
                  arrowprops=dict(arrowstyle='->', color='gray', lw=0.8))

ax_c.set_xlabel('$J_0$', fontsize=14)
ax_c.set_ylabel('$n^*(J_0)$', fontsize=14)
ax_c.set_title(f'(c) Full decay time ($|C|<{EPSILON}$ for '
               f'{CONSEC} periods)', fontweight='bold')
ax_c.legend(fontsize=10)
ax_c.grid(True, alpha=0.3, which='both')
ax_c.xaxis.set_minor_locator(AutoMinorLocator())

fig2.suptitle(f'Decay metrics vs $J_0$ — {suptxt}', fontsize=12, y=1.02)
fig2.tight_layout()
plt.show()